 "content": "def transform(grid):
    from collections import Counter

    height, width = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    visited = set()
    components = []
    for r in range(height):
        for c in range(width):
            color = grid[r][c]
            if color == background or (r, c) in visited:
                continue
            stack = [(r, c)]
            visited.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < height and 0 <= xx < width and
                            (yy, xx) not in visited and grid[yy][xx] == color):
                        visited.add((yy, xx))
                        stack.append((yy, xx))
            components.append((color, cells))

    # Recolor the largest connected object of a color appearing in multiple
    # disconnected shapes; the small repeated shapes are markers/examples.
    by_color = {}
    for color, cells in components:
        by_color.setdefault(color, []).append(cells)
    candidates = []
    for color, objects in by_color.items():
        if len(objects) >= 2:
            largest = max(objects, key=len)
            if len(largest) >= 10:
                candidates.append((len(largest), color, largest))
    if not candidates:
        return [row[:] for row in grid]

    _, color, target = max(candidates)
    # The recoloring is to the color of the short one-cell guide at the lower
    # edge of the canvas (here 7); if absent, use the most common small-object
    # color as a conservative fallback.
    guide_color = None
    for r in range(height - 1, max(-1, height - 4), -1):
        runs = []
        c = 0
        while c < width:
            if grid[r][c] != background:
                col = grid[r][c]
                end = c + 1
                while end < width and grid[r][end] == col:
                    end += 1
                if end - c >= 4:
                    runs.append((end - c, col))
                c = end
            else:
                c += 1
        if runs:
            guide_color = max(runs)[1]
            break
    if guide_color is None:
        guide_color = color
    out = [row[:] for row in grid]
    for r, c in target:
        out[r][c] = guide_color
    return out
